CREATE OR REPLACE FUNCTION public.handle_new_gpatrol_user()
RETURNS TRIGGER AS $$
DECLARE
    user_count INTEGER;
BEGIN
    SELECT COUNT(*) INTO user_count FROM public.g_patrol;
    IF user_count = 0 THEN
        NEW.role := 'admin'; -- บัญชีแรกสุดให้สิทธิ์เป็น Admin
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE TRIGGER on_gpatrol_user_created
    BEFORE INSERT ON public.g_patrol
    FOR EACH ROW EXECUTE FUNCTION public.handle_new_gpatrol_user();"

