    --card-blue: #3b82f6;
    --card-green: #10b981;
    --card-red: #ef4444;

    --border-color: #e2e8f0;
}

/* General Reset */
* {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
    font-family: var(--font-body);
}

body {
    background-color: var(--bg-primary);
