const supabase = createClient(supabaseUrl, supabaseKey);

async function checkUser() {
    try {
        const { data, error } = await supabase
            .from('g_patrol_users')
            .select('*')
            .eq('username', 'mgr001')
            .maybeSingle();

        if (error) {
            console.error('Error fetching user:', error);
            return;
        }

        console.log('User Record:', JSON.stringify(data, null, 2));
    } catch (e) {
        console.error('Exception:', e);
    }
}

checkUser();
"

"const supabaseUrl = 'https://yurtzwdpfmwytvpaokwi.supabase.co';
const supabaseKey = 'sb_publishable_ZgDsjezCHGXk50TUxnJJ8A_BDa2I2CQ';

async function checkUser() {
    const url = `${supabaseUrl}/rest/v1/g_patrol_users?username=eq.mgr001`;
    try {
        const response = await fetch(url, {
            headers: {
                'apikey': supabaseKey,
                'Authorization': `Bearer ${supabaseKey}`
            }
        });

        if (!response.ok) {
            console.error('HTTP Error:', response.status, response.statusText);
            return;
        }

        const data = await response.json();
        console.log('User Record:', JSON.stringify(data, null, 2));
    } catch (e) {
        console.error('Exception:', e);
    }
}

checkUser();
"

