const { createClient } = require('@supabase/supabase-js');
const client = createClient(supabaseUrl, supabaseKey);

async function runTest() {
    try {
        console.log('1. Fetching assets...');
        const { data: assets, error: assetsError } = await client
            .from('g_patrol_checkpoints')
            .select('*, g_patrol_users(display_name)');

        if (assetsError) {
            console.error('Assets Error:', assetsError);
        } else {
            console.log(`Assets count: ${assets.length}`);
        }

        console.log('2. Fetching audit records...');
        const { data: auditedList, error: auditError } = await client
            .from('g_patrol_audit_records')
            .select('asset_id')
            .eq('fiscal_year', 2569);

        if (auditError) {
            console.error('Audit Error:', auditError);
        } else {
            console.log(`Audit records count: ${auditedList.length}`);
        }
    } catch (e) {
        console.error('Catch Exception:', e);
    }
}

runTest();
"

